<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { useQuasar } from 'quasar'
import { useRouter } from 'vue-router'
import { api } from 'boot/axios'
import SupportTicketsPanel from 'components/SupportTicketsPanel.vue'
const $q=useQuasar(),router=useRouter(),active=ref('overview'),loading=ref(false),summary=ref({}),affiliate=ref({}),coupons=ref([]),purchases=ref([]),withdrawals=ref([]),notifications=ref([]),notices=ref(false)
const profile=reactive({name:'',phone:'',instagram:'',tiktok:'',youtube:''}),withdrawal=reactive({amount:null,description:''})
const headers=()=>({headers:{Authorization:'Bearer '+localStorage.getItem('aito_affiliate_token')}})
const money=v=>Number(v||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'}),cents=v=>money(Number(v||0)/100)
const date=v=>new Date(v).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'})
const tabs=[{id:'overview',label:'Resumo',icon:'mdi-view-dashboard-outline'},{id:'coupons',label:'Meus cupons',icon:'mdi-ticket-percent-outline'},{id:'sales',label:'Minhas vendas',icon:'mdi-chart-line'},{id:'withdrawals',label:'Saques',icon:'mdi-bank-transfer-out'},{id:'tickets',label:'Chamados',icon:'mdi-lifebuoy'},{id:'profile',label:'Meu perfil',icon:'mdi-account-outline'}]
const unread=computed(()=>notifications.value.filter(n=>!n.read).length)
const columns=[{name:'date',label:'Confirmada em',field:r=>date(r.paidAt),align:'left'},{name:'coupon',label:'Seu cupom',field:'couponCode',align:'left'},{name:'amount',label:'Valor da venda',field:r=>cents(r.amountCents)},{name:'commission',label:'Sua comissão',field:r=>cents(r.commissionCents)}]
const terms=(type,value)=>type==='percent'?value+'%':money(value)
const status=v=>({withdrawal_requested:'Em análise',withdrawal_completed:'Pago',withdrawal_rejected:'Recusado'})[v]||v
function error(e){$q.notify({type:'negative',message:e.response?.data?.message||'Não foi possível concluir a operação.'})}
async function load(){loading.value=true;try{const [me,s,c,p,w,n]=await Promise.all([api.get('/affiliate/me',headers()),api.get('/affiliate/summary',headers()),api.get('/affiliate/coupons',headers()),api.get('/affiliate/purchases',headers()),api.get('/affiliate/withdrawals',headers()),api.get('/affiliate/notifications',headers())]);affiliate.value=me.data.data.affiliate;Object.assign(profile,affiliate.value);summary.value=s.data.data;coupons.value=c.data.data||[];purchases.value=p.data.data||[];withdrawals.value=w.data.data||[];notifications.value=n.data.data||[]}catch(e){error(e)}finally{loading.value=false}}
async function save(){loading.value=true;try{affiliate.value=(await api.put('/affiliate/me',{name:profile.name,phone:profile.phone,instagram:profile.instagram,tiktok:profile.tiktok,youtube:profile.youtube},headers())).data.data;$q.notify({type:'positive',message:'Perfil salvo.'})}catch(e){error(e)}finally{loading.value=false}}
async function requestWithdrawal(){loading.value=true;try{await api.post('/affiliate/withdrawals',withdrawal,headers());Object.assign(withdrawal,{amount:null,description:''});await load();$q.notify({type:'positive',message:'Solicitação enviada. Acompanhe o status em Saques.'})}catch(e){error(e)}finally{loading.value=false}}
async function copy(coupon){try{await navigator.clipboard.writeText(window.location.origin+'/whatsapp-solucoes?cupom='+encodeURIComponent(coupon.title));$q.notify({type:'positive',message:'Link com seu cupom copiado.'})}catch{$q.notify({type:'info',message:coupon.title})}}
async function read(n){if(!n.read){try{await api.patch('/affiliate/notifications/'+n._id+'/read',{},headers());n.read=true}catch(e){error(e)}}}
async function logout(){try{await api.post('/auth/logout',{},headers());localStorage.removeItem('aito_affiliate_token');localStorage.removeItem('aito_affiliate_user');router.push('/affiliate/login')}catch(e){error(e)}}
onMounted(load)
</script>
<template>
  <q-layout view="hHh Lpr fFf" class="partner-app"><q-header class="partner-header"><q-toolbar><router-link to="/affiliate" class="partner-brand"><img src="/aito-logo-restored.png" alt=""/><strong>AitoSoftwares</strong></router-link><q-space/><span>{{affiliate.name}}</span><q-btn flat round icon="mdi-bell-outline" aria-label="Notificações" @click="notices=true"><q-badge v-if="unread" floating color="negative">{{unread}}</q-badge></q-btn><q-btn flat round icon="mdi-logout" aria-label="Sair" @click="logout"/></q-toolbar></q-header><q-page-container><q-page class="partner-page"><nav><button v-for="item in tabs" :key="item.id" type="button" :class="{selected:active===item.id}" @click="active=item.id"><q-icon :name="item.icon"/>{{item.label}}</button></nav>
    <section v-if="active==='overview'" class="partner-overview"><header><small>SEU PAINEL DE AFILIADO</small><h1>Seu próximo resultado<br/>começa com uma indicação.</h1><p>Kit AitoNotify + WhatsApp BotBuilder. Vendas confirmadas, comissões claras e seu progresso em um só lugar.</p></header><div class="partner-stats"><article><span>Disponível para saque</span><strong>{{money(summary.available)}}</strong><small>Ganhos menos saques reservados ou pagos</small></article><article><span>Comissões acumuladas</span><strong>{{money(summary.earned)}}</strong><small>{{summary.purchases||0}} venda(s) confirmada(s)</small></article><article class="partner-rank"><span>Seu lugar no ranking geral</span><strong>{{summary.rank?.position?'#'+summary.rank.position:'—'}}</strong><small>{{summary.rank?.position?'Entre '+summary.rank.participants+' afiliados com vendas':'Sua primeira venda entra no ranking'}}</small></article></div><div class="partner-tip"><q-icon name="mdi-shield-check-outline" size="28px"/><div><strong>Resultados só seus.</strong><p>Você vê apenas suas vendas e sua posição. A classificação considera vendas confirmadas, com desempate pela comissão. Os números e os dados dos outros afiliados são privados.</p></div></div><q-btn unelevated no-caps color="teal-8" icon="mdi-ticket-percent-outline" label="Divulgar meus cupons" @click="active='coupons'"/></section>
    <section v-else-if="active==='coupons'" class="partner-section"><header><h2>Seus códigos, suas indicações.</h2><p>O cupom usa o preço atual do kit no checkout. A comissão é calculada sobre o valor pago após o desconto.</p></header><div class="partner-coupons"><article v-for="coupon in coupons" :key="coupon._id"><div class="row justify-between items-center"><strong>{{coupon.title}}</strong><q-badge :color="coupon.active?'teal-8':'grey-7'">{{coupon.active?'Ativo':'Pausado'}}</q-badge></div><p>{{coupon.description}}</p><dl><div><dt>Desconto para o cliente</dt><dd>{{terms(coupon.discountType,coupon.discountValue)}}</dd></div><div><dt>Sua comissão por venda</dt><dd>{{terms(coupon.commissionType,coupon.commissionValue)}}</dd></div><div><dt>Vendas confirmadas</dt><dd>{{coupon.usageCount||0}}</dd></div></dl><q-btn outline no-caps icon="mdi-link" label="Copiar link com cupom" :disable="!coupon.active" @click="copy(coupon)"/></article><p v-if="!coupons.length">A equipe ainda não vinculou um cupom ao seu perfil. Abra um chamado para conversar com a gente.</p></div></section>
    <section v-else-if="active==='sales'" class="partner-section"><h2>Vendas que usaram seu cupom</h2><q-table flat bordered wrap-cells row-key="_id" :rows="purchases" :columns="columns" :loading="loading" no-data-label="Sua primeira venda aparecerá aqui"/><p class="text-caption">Valores são confirmados pelo pagamento. Alterações de cupom afetam novas compras; pedidos existentes mantêm suas regras.</p></section>
    <section v-else-if="active==='withdrawals'" class="partner-section"><h2>Receba suas comissões.</h2><p>Saldo disponível: <strong>{{money(summary.available)}}</strong> · Já pago: {{money(summary.paid)}}</p><q-form @submit.prevent="requestWithdrawal" class="partner-form"><q-input v-model="withdrawal.amount" outlined type="number" min="50" step="0.01" prefix="R$" label="Valor do saque (mínimo R$ 50)" :rules="[v=>Number(v)>=50||'Valor mínimo de R$ 50.']"/><q-input v-model="withdrawal.description" outlined type="textarea" autogrow maxlength="5000" label="Observações para a equipe"/><q-btn unelevated no-caps color="teal-8" type="submit" label="Solicitar saque" :loading="loading"/></q-form><div v-for="item in withdrawals" :key="item._id" class="partner-withdrawal"><strong>{{money(item.amount)}}</strong><span>{{status(item.status)}}</span><small>{{date(item.createdAt)}}</small></div></section>
    <section v-else-if="active==='tickets'" class="partner-section"><SupportTicketsPanel affiliate/></section>
    <section v-else class="partner-section"><h2>Seu perfil de parceiro</h2><q-form class="partner-form" @submit.prevent="save"><q-input v-model="profile.name" outlined label="Nome" :rules="[v=>Boolean(v?.trim())||'Informe seu nome.']"/><q-input :model-value="affiliate.email" outlined readonly label="E-mail de acesso" hint="Para alterar o e-mail, abra um chamado."/><q-input v-model="profile.phone" outlined label="Telefone"/><q-input v-model="profile.instagram" outlined label="Instagram"/><q-btn unelevated no-caps type="submit" color="teal-8" label="Salvar perfil" :loading="loading"/></q-form></section>
  </q-page></q-page-container><q-dialog v-model="notices"><q-card class="partner-notices"><q-card-section class="row items-center justify-between"><strong>Notificações</strong><q-btn flat round icon="mdi-close" v-close-popup/></q-card-section><q-card-section><button v-for="n in notifications" :key="n._id" type="button" @click="read(n)"><strong>{{n.title}}</strong><span>{{n.message}}</span><small>{{n.read?'Lida':'Nova'}}</small></button><p v-if="!notifications.length">Nenhuma notificação.</p></q-card-section></q-card></q-dialog></q-layout>
</template>
<style scoped>
