section p{font-size:13px;line-height:1.8;color:#75917f}.partner-coupons{display:grid;grid-template-columns:repeat(auto-fill,minmax(270px,1fr));gap:20px}.partner-coupons article{background:#fff;border:1px solid #d5e8dc;padding:24px;border-radius:18px}.partner-coupons article>div>strong{font-size:23px;color:#187046;letter-spacing:.05em}.partner-coupons dl div{display:flex;justify-content:space-between;font-size:12px;padding:12px 0;gap:10px;border-bottom:1px solid #e5eee9}.partner-coupons dt{color:#8ba291}.partner-coupons dd{margin:0;font-weight:750}.partner-coupons .q-btn{margin-top:15px;color:#288855}.partner-form{max-width:600px;display:grid;gap:20px}.partner-form>.q-btn{justify-self:start}.partner-withdrawal{display:flex;align-items:center;gap:20px;background:#fff;border:1px solid #d4e8dc;border-radius:12px;padding:18px}.partner-withdrawal small{margin-left:auto;color:#85a18e}.partner-section :deep(.q-table__container){background:#fff;border-color:#d5e8dc;color:#355c43;border-radius:15px}.partner-section :deep(.q-field__control){background:#fff;color:#31523d}.partner-section :deep(.q-field__native),.partner-section :deep(.q-field__label){color:#406a4d}.partner-section :deep(.portal-module),.partner-section :deep(.portal-module__table td),.partner-section :deep(.portal-module__table th){color:#355c43}.partner-section :deep(.portal-module__eyebrow){color:#3c9562}.partner-notices{width:min(500px,95vw);background:#f5fcf8;color:#244b36;border-radius:20px}.partner-notices button{display:grid;gap:10px;width:100%;padding:16px;text-align:left;color:#355b42;background:#fff;border:1px solid #d2e7d9;margin-bottom:10px;border-radius:10px}.partner-notices span{font-size:13px}.partner-notices small{color:#5a8e6b}@media(max-width:700px){.partner-stats{grid-template-columns:1fr 1fr}.partner-stats .partner-rank{grid-column:1/-1}.partner-page{padding:16px}.partner-overview{padding-top:30px}.partner-stats article{padding:20px}.partner-stats strong{font-size:24px}.partner-header .q-toolbar>span{display:none}.partner-brand strong{font-size:15px}.partner-page nav{gap:6px}.partner-page nav button{padding:10px 12px;font-size:11px}}
</style>
